# -*- coding: utf-8 -*-
from gen2 import *

m1 = M(('Независимые события: площадь', 'Independent events: area'),
 [('r', 'a', 'P(A)', 'P(A)', 0.1, 0.9, 0.1, 0.6), ('r', 'b', 'P(B)', 'P(B)', 0.1, 0.9, 0.1, 0.5)],
 [('P(A и B) = P(A)·P(B)', 'P(A and B) = P(A)·P(B)'), ('P(A или B)', 'P(A or B)'), ('P(ни A, ни B)', 'P(neither A nor B)')],
 'Если события независимы, вероятность наступления обоих равна произведению. На квадрате площадью 1 это площадь прямоугольника a × b.', 'If events are independent the probability that both occur is the product. On a square of area 1 this is the area of an a × b rectangle.', ('Единичный квадрат вероятностей', 'The unit probability square'),
 r'''const S=200,x0=200,y0=25;let g=R(x0,y0,S,S,COL.bg,COL.ink,2,0)+R(x0,y0+S*(1-v.b),S*v.a,S*v.b,COL.b+"99",COL.ink,2,0)+L(x0+S*v.a,y0,x0+S*v.a,y0+S,COL.a,2,0)+L(x0,y0+S*(1-v.b),x0+S,y0+S*(1-v.b),COL.a,2,0)+TX(x0+S*v.a/2,y0+S*(1-v.b/2)+5,fnum(v.a*v.b,3),COL.ink,16,"middle",700)+TX(x0+S*v.a/2,y0-6,"A",COL.a,14,"middle",700)+TX(x0-12,y0+S*(1-v.b/2),"B",COL.a,14,"middle",700);
 return {svg:g,st:[fnum(v.a*v.b,3),fnum(v.a+v.b-v.a*v.b,3),fnum((1-v.a)*(1-v.b),3)],fb:U("P(A или B) = P(A) + P(B) − P(A и B): пересечение вычитается.","P(A or B) = P(A) + P(B) − P(A and B): the overlap is subtracted.")}''', '0 0 600 250')

m2 = M(('Условная вероятность и контроль качества', 'Conditional probability and quality control'),
 [('r', 'pr', 'Доля бракованных деталей, %', 'Share of faulty parts, %', 1, 30, 1, 5), ('r', 'se', 'Прибор находит брак, %', 'The device detects a fault, %', 70, 99, 1, 95), ('r', 'fp', 'Ложная тревога на исправных, %', 'False alarm on good parts, %', 1, 20, 1, 8)],
 [('Тревога подаётся (из 1000 деталей)', 'Alarm is raised (of 1000 parts)'), ('Из них действительно брак', 'Of them really faulty'), ('P(брак | тревога)', 'P(faulty | alarm)')],
 'Условная вероятность P(A | B) — вероятность A, когда уже известно, что B произошло. Удобно считать «на 1000 деталей»: так видно, откуда берётся результат (формула Байеса).', 'The conditional probability P(A | B) is the probability of A when B is already known to have occurred. It is handy to count “per 1000 parts”: then we see where the result comes from (Bayes’ formula).', ('Состав сработавших тревог', 'The make-up of the alarms'),
 r'''const bad=10*v.pr,good=1000-bad,tp=bad*v.se/100,fpp=good*v.fp/100,al=tp+fpp;const W=420,x0=90;let g=R(x0,50,W,50,COL.bg,COL.ink,2,0)+R(x0,50,W*bad/1000,50,COL.b,COL.ink,1,0)+TX(x0,40,U("1000 деталей: брак — синим","1000 parts: faulty in blue"),COL.ink,12,"start")+R(x0,150,W*al/1000,50,COL.bg,COL.ink,2,0)+R(x0,150,W*tp/1000,50,COL.c,COL.ink,1,0)+R(x0+W*tp/1000,150,W*fpp/1000,50,COL.a,COL.ink,1,0)+TX(x0,140,U("тревоги: брак (зелёный) и ложные (красный)","alarms: faulty (green) and false (red)"),COL.ink,12,"start");
 return {svg:g,st:[fnum(al,0),fnum(tp,0),fnum(tp/al*100,1)+"%"],fb:U("Если брак редок, то даже хороший прибор даёт много ложных тревог: доля настоящего брака среди тревог может быть небольшой.","If faults are rare, even a good device gives many false alarms: the share of real faults among alarms may be small.")}''', '0 0 600 225')

m3 = M(('С возвратом и без возврата', 'With and without replacement'),
 [('r', 'r', 'Красных шаров', 'Red balls', 1, 10, 1, 4), ('r', 'b', 'Синих шаров', 'Blue balls', 1, 10, 1, 6), ('s', 'rep', 'Шар после извлечения', 'After drawing the ball', ['возвращают', 'не возвращают'], ['is returned', 'is not returned'], 1)],
 [('P(первый красный)', 'P(first red)'), ('P(второй красный | первый красный)', 'P(second red | first red)'), ('P(оба красные)', 'P(both red)')],
 'Если шар возвращают, извлечения независимы: P = (r/N)². Если нет, состав урны меняется: P = r/N · (r − 1)/(N − 1).', 'If the ball is returned the draws are independent: P = (r/N)². If not, the urn changes: P = r/N · (r − 1)/(N − 1).', ('Урна с шарами', 'An urn with balls'),
 r'''const N=v.r+v.b;let g="";for(let i=0;i<N;i++){const x=70+(i%10)*46,y=50+Math.floor(i/10)*50;g+=C(x,y,18,i<v.r?COL.a:COL.b,COL.ink,2)}
 const p1=v.r/N,p2=v.rep===0?v.r/N:(N>1?(v.r-1)/(N-1):0);
 return {svg:g,st:[fnum(p1,4),fnum(p2,4),fnum(p1*p2,4)],fb:v.rep===0?U("С возвратом события независимы: второй шар не знает о первом.","With replacement the events are independent: the second ball does not “know” about the first."):U("Без возврата события зависимы: после красного шара красных стало меньше.","Without replacement the events are dependent: after a red ball fewer reds remain.")}''', '0 0 600 130')

chapter('72', '72-independent-events.html', 'X', ('Независимые события и условная вероятность', 'Independent events and conditional probability'),
 ('Когда вероятности умножают, что значит «при условии» и почему редкое событие трудно найти даже хорошим тестом.', 'When probabilities are multiplied, what “given that” means and why a rare event is hard to find even with a good test.'),
 ('На заводе прибор находит бракованную деталь в 95 % случаев, а на исправной ошибочно срабатывает в 8 % случаев. Брак составляет 5 % деталей. Прибор просигналил тревогу. Какова вероятность, что деталь действительно бракованная — около 95 %?', 'At a factory a device detects a faulty part 95 % of the time, and falsely alarms on a good part 8 % of the time. Faults make up 5 % of parts. The device raised an alarm. What is the probability that the part really is faulty — about 95 %?'),
 ('Разгадка: примерно 38 %', 'The answer: about 38 %'),
 ('Возьмём 1000 деталей: 50 бракованных и 950 исправных. Прибор поймает 47,5 брака и ошибочно сработает на 76 исправных. Тревог 123,5, из них настоящих 47,5, то есть ≈ 38 %. Интуиция путает P(тревога | брак) = 95 % с P(брак | тревога). Когда брак редок, ложных тревог много. (Числа придуманы для задачи.)', 'Take 1000 parts: 50 faulty and 950 good. The device catches 47.5 faults and falsely alarms on 76 good ones. There are 123.5 alarms of which 47.5 are real, i.e. about 38 %. Intuition mixes up P(alarm | fault) = 95 % with P(fault | alarm). When faults are rare, false alarms are many. (The numbers are invented for the exercise.)'),
 [S('ind', 'Независимые события', 'Independent events', ('События A и B <strong>независимы</strong>, если наступление одного не меняет вероятность другого: <strong>P(A и B) = P(A)·P(B)</strong>. Монета, брошенная дважды: P(два орла) = 1/4. Для событий, которые вместе не исключают друг друга: P(A или B) = P(A) + P(B) − P(A и B).', 'Events A and B are <strong>independent</strong> if one occurring does not change the probability of the other: <strong>P(A and B) = P(A)·P(B)</strong>. A coin tossed twice: P(two heads) = 1/4. For events that do not exclude each other: P(A or B) = P(A) + P(B) − P(A and B).'),
    ('P(A и B) = P(A)·P(B)', '', 'P(A and B) = P(A)·P(B)'), m1),
  S('cond', 'Условная вероятность', 'Conditional probability', ('<strong>P(A | B) = P(A и B) / P(B)</strong> — вероятность A, если B уже известно. Отсюда общее правило умножения: P(A и B) = P(B)·P(A | B). Для независимых событий P(A | B) = P(A). Формула Байеса позволяет «перевернуть» условие: P(брак | тревога) по P(тревога | брак).', '<strong>P(A | B) = P(A and B) / P(B)</strong> — the probability of A when B is known. Hence the general multiplication rule: P(A and B) = P(B)·P(A | B). For independent events P(A | B) = P(A). Bayes’ formula lets us “flip” the condition: P(fault | alarm) from P(alarm | fault).'),
    ('P(A | B) = P(A и B) / P(B)', '', 'P(A | B) = P(A and B) / P(B)'), m2),
  S('urn', 'Урна: с возвратом и без', 'An urn: with and without replacement', ('Если шар возвращают, извлечения независимы. Если нет, второе извлечение зависит от первого: P(оба красные) = r/N · (r − 1)/(N − 1). Такие «зависимые» задачи решают умножением условных вероятностей по ветвям дерева.', 'If the ball is returned the draws are independent. If not, the second draw depends on the first: P(both red) = r/N · (r − 1)/(N − 1). Such “dependent” problems are solved by multiplying conditional probabilities along the branches of the tree.'),
    ('P(оба) = P(1-й)·P(2-й | 1-й)', '', 'P(both) = P(1st)·P(2nd | 1st)'), m3)],
 [TK(('Независимые', 'Independent'), ('P(A) = 0,3, P(B) = 0,5, события независимы. P(A и B)?', 'P(A) = 0.3, P(B) = 0.5, the events are independent. P(A and B)?'), '', '0,15.', '0.15.'),
  TK(('Монеты', 'Coins'), ('Вероятность трёх орлов подряд?', 'The probability of three heads in a row?'), '', '(1/2)³ = 1/8.', '1/8.'),
  TK(('Без возврата', 'Without replacement'), ('В урне 3 красных и 2 синих. Вынули 2 без возврата. P(оба красные)?', 'An urn has 3 red and 2 blue. Two are drawn without replacement. P(both red)?'), '', '3/5 · 2/4 = 3/10.', '3/10.'),
  TK(('Условная', 'Conditional'), ('P(A и B) = 0,2, P(B) = 0,5. Найдите P(A | B).', 'P(A and B) = 0.2, P(B) = 0.5. Find P(A | B).'), '', '0,2/0,5 = 0,4.', '0.4.'),
  TK(('Хотя бы одно', 'At least one'), ('Два независимых датчика срабатывают с вероятностью 0,9 каждый. P(сработал хотя бы один)?', 'Two independent sensors each fire with probability 0.9. P(at least one fires)?'), '', '1 − 0,1·0,1 = 0,99.', '0.99.')],
 [Q('Независимые A и B: P(A и B) =', 'Independent A and B: P(A and B) =', 'P(A)·P(B)', 'P(A)+P(B)', 'P(A)−P(B)', ('Произведение.', 'The product.')),
  Q('P(A | B) =', 'P(A | B) =', 'P(A и B)/P(B)', 'P(A)·P(B)', 'P(B)/P(A)', ('Определение.', 'Definition.')),
  Q('Две монеты: P(два орла)', 'Two coins: P(two heads)', '1/4', '1/2', '1/3', ('1/2 · 1/2.', '1/2 · 1/2.')),
  Q('Шар не возвращают — извлечения', 'The ball is not returned — the draws are', ('зависимы', 'dependent'), ('независимы', 'independent'), ('невозможны', 'impossible'), ('Состав урны меняется.', 'The urn changes.')),
  Q('Для независимых P(A | B) =', 'For independent events P(A | B) =', 'P(A)', 'P(B)', '0', ('B ничего не меняет.', 'B changes nothing.')),
  Q('P(тревога | брак) и P(брак | тревога) —', 'P(alarm | fault) and P(fault | alarm) are', ('разные величины', 'different quantities'), ('одно и то же', 'the same'), ('всегда равны', 'always equal'), ('Условие «перевёрнуто».', 'The condition is flipped.')),
  Q('Редкий брак + хороший прибор → доля настоящего брака среди тревог', 'Rare faults + a good device → the share of real faults among alarms', ('может быть небольшой', 'may be small'), ('всегда около 100 %', 'is always about 100 %'), ('равна 0', 'is 0'), ('Много ложных тревог.', 'Many false alarms.')),
  Q('P(A или B) =', 'P(A or B) =', 'P(A)+P(B)−P(A и B)', 'P(A)·P(B)', 'P(A)+P(B)+P(A и B)', ('Вычитаем пересечение.', 'Subtract the overlap.'))],
 src=[('Wikipedia: Conditional probability', 'https://en.wikipedia.org/wiki/Conditional_probability'), ('Wikipedia: Independence (probability theory)', 'https://en.wikipedia.org/wiki/Independence_(probability_theory)'), ('Wikipedia: Bayes’ theorem', 'https://en.wikipedia.org/wiki/Bayes%27_theorem'), ('OpenStax: Introductory Statistics 2e', 'https://openstax.org/details/books/introductory-statistics-2e')],
 note=('Заводской прибор и числа придуманы для атласа.', 'The factory device and the numbers are invented for the atlas.'))
